#!/usr/bin/env bash
# Merge CIVWATCH's Android network policy into the manifest generated by
# `flutter create . --platforms=android`. Run from the repo root, after create.
set -euo pipefail

M=android/app/src/main/AndroidManifest.xml

if ! grep -q 'networkSecurityConfig' "$M"; then
  sed -i 's#<application#<application android:networkSecurityConfig="@xml/network_security_config" android:usesCleartextTraffic="false"#' "$M"
fi

# Flutter only declares INTERNET in the debug/profile manifests; release needs it.
if ! grep -q 'android.permission.INTERNET' "$M"; then
  sed -i 's#<application#<uses-permission android:name="android.permission.INTERNET"/>\n    <application#' "$M"
fi

grep -q 'networkSecurityConfig' "$M"
grep -q 'android.permission.INTERNET' "$M"
grep -q '<activity' "$M"
